// Concatenates supabase/migrations/*.sql (in order) into supabase/bundle/setup.sql
// so the whole schema can be pasted into the Supabase SQL Editor in one go when
// the Supabase CLI is not available. The CLI (`supabase db push`) remains the
// preferred way to apply migrations.
import { mkdirSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
import path from "node:path";

const root = process.cwd();
const dir = path.join(root, "supabase", "migrations");
const files = readdirSync(dir).filter((f) => f.endsWith(".sql")).sort();

const parts = [
  "-- Generated by `npm run db:bundle`. Do not edit; edit supabase/migrations instead.",
  `-- Contains ${files.length} migrations. Run once on a NEW, empty Supabase project.`,
  "begin;",
];
for (const file of files) {
  parts.push(`\n-- ===== ${file} =====\n`, readFileSync(path.join(dir, file), "utf8"));
}
parts.push("\ncommit;\n");

mkdirSync(path.join(root, "supabase", "bundle"), { recursive: true });
const out = path.join(root, "supabase", "bundle", "setup.sql");
writeFileSync(out, parts.join("\n"));
console.log(`Wrote ${path.relative(root, out)} (${files.length} migrations)`);
